window.createPSCatStudio = async function () {
  const bundle = window.PSCAT_STUDIO_BUNDLE;
  const packed = Uint8Array.from(atob(bundle.wasmGzipBase64), c => c.charCodeAt(0));
  const stream = new Blob([packed]).stream().pipeThrough(new DecompressionStream('gzip'));
  const bytes = await new Response(stream).arrayBuffer();
  const url = URL.createObjectURL(new Blob([bundle.apiSource], {type:'text/javascript'}));
  try {
    const {Pscat} = await import(url);
    return await Pscat.instantiate(bytes);
  } finally { URL.revokeObjectURL(url); }
};
